SINA_SMART["hemato1-wbc-1"] = {"lecture":"hemato1-wbc-1","title":"White blood cells, part I: granulocytes","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-wbc-1:e0","text":"WBC 4-10 G/L in adults; leukocytosis > 10, leukopenia < 4.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e1","text":"Always interpret the differential in absolute values.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e2","text":"Neutrophils 1,800-7,000/mm³; from GMP; driven by G-CSF.","topic":"Neutrophils","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e3","text":"Pools: marrow storage, circulating, marginating, tissue.","topic":"Neutrophils","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e4","text":"Severe neutropenia < 500 = agranulocytosis; fever = emergency; necrotic tonsillitis without pus.","topic":"Neutrophils","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e5","text":"Neutropenia: ↓ production, ↑ loss, pseudoneutropenia.","topic":"Neutrophils","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e6","text":"Neutrophilia: bacterial infection (10-25 G/L), inflammation, steroids, tobacco, pregnancy, MPN.","topic":"Neutrophils","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e7","text":"Eosinophils 0-400/mm³; bilobed; IL-5; 18 h in blood.","topic":"Eosinophils and basophils","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e8","text":"Eosinophilia: parasites, allergy (< 1,000) vs clonal (> 1,000); HES > 1,500.","topic":"Eosinophils and basophils","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-wbc-1:e9","text":"Basophils: histamine granules; normal < 200/mm³ in this lecture.","topic":"Eosinophils and basophils","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1cyvoi3":"a","5vgyog":"a","mvczku":"a","136reft":"a","14g5iym":"a","r1zy1o":"a","1kwolbh":"a","b82khx":"a","ch55vw":"a","15khw61":"a","b7uff3":"a","116rdtj":"a","ykiku2":"a","vcrwjx":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-wbc-1:e0":{"s":0,"u":["WBC 4-10 G/L in adults; leukocytosis > 10, leukopenia < 4.","Leukocytosis &gt; 10,000/mm³; leukopenia &lt; 4,000/mm³.","Adult normal count: 4-10 G/L (4,000-10,000/mm³); higher in children (9-30 G/L at birth, 6-18 at 6 months)."],"dp":[]},"hemato1-wbc-1:e1":{"s":0,"u":["Always interpret the differential in absolute values.","The differential must be read in absolute values : 90% lymphocytes with 3,500 WBC is a normal 3,150 lymphocytes/mm³."],"dp":[]},"hemato1-wbc-1:e2":{"s":1,"u":["Neutrophils 1,800-7,000/mm³; from GMP; driven by G-CSF.","Produced in the marrow from the GMP (shared with monocytes): myeloblast → promyelocyte → myelocyte → metamyelocyte → band → segmented neutrophil, controlled by IL-3, GM-CSF and especially G-CSF (survival, proliferation, release from marrow, activation; recombinant G-CSF treats neutropenia).","Neutropenia : mild (1,000-1,800), moderate (500-1,000), severe &lt; 500 = agranulocytosis : fever 39-40 °C, chills, necrotic tonsillitis without pus , lung and skin infections: fever + agranulocytosis = emergency ."],"dp":[]},"hemato1-wbc-1:e3":{"s":1,"u":["Pools: marrow storage, circulating, marginating, tissue.","Compartments: marrow (with a storage pool), blood ( circulating and marginating pools ) and tissues; infection, inflammation, stress, steroids and exercise mobilise them."],"dp":[]},"hemato1-wbc-1:e4":{"s":1,"u":["Severe neutropenia < 500 = agranulocytosis; fever = emergency; necrotic tonsillitis without pus.","Neutropenia : mild (1,000-1,800), moderate (500-1,000), severe &lt; 500 = agranulocytosis : fever 39-40 °C, chills, necrotic tonsillitis without pus , lung and skin infections: fever + agranulocytosis = emergency ."],"dp":[{"h":"Why fever with agranulocytosis is an emergency","t":"Neutrophils are the first line against bacteria and fungi. With fewer than 500 per mm³, bacteria from the patient's own gut, mouth and skin can invade and spread within hours, often without the usual signs such as pus or a clear focus, because there are no neutrophils to create them. Any fever in such a patient needs immediate cultures and broad-spectrum antibiotics before results arrive. Source: the lecture's neutropenia semiology slides."}]},"hemato1-wbc-1:e5":{"s":1,"u":["Neutropenia: ↓ production, ↑ loss, pseudoneutropenia.","Causes: decreased production (aplastic anaemia, megaloblastic anaemia with hypersegmented neutrophils, drugs and chemotherapy, radiation, toxins, acute leukaemia, myelodysplasia, rare congenital forms), increased loss (infections such as tuberculosis, typhoid, brucellosis, HIV; immune neutropenia, e.g. lupus; hypersplenism) and pseudoneutropenia (excess marginating pool, e.g. in some Black people; normalises after exercise)."],"dp":[]},"hemato1-wbc-1:e6":{"s":1,"u":["Neutrophilia: bacterial infection (10-25 G/L), inflammation, steroids, tobacco, pregnancy, MPN.","Neutrophilia (&gt; 7,000/mm³): physiological (exercise, newborns, pregnancy, childbirth), tobacco, steroids, bacterial infections (typically 10,000-25,000/mm³, with raised CRP and procalcitonin), inflammation and tissue damage (burns, trauma, myocardial infarction), myeloproliferative disorders.","Compartments: marrow (with a storage pool), blood ( circulating and marginating pools ) and tissues; infection, inflammation, stress, steroids and exercise mobilise them."],"dp":[]},"hemato1-wbc-1:e7":{"s":2,"u":["Eosinophils 0-400/mm³; bilobed; IL-5; 18 h in blood.","Eosinophils : normal 0-400/mm³; 12-15 µm, usually bilobed , cytoplasm full of orange granules; about 18 hours in blood , then weeks in tissues (airways, lung, skin, gut), never returning; production mainly driven by IL-5 (plus IL-3, GM-CSF)."],"dp":[]},"hemato1-wbc-1:e8":{"s":2,"u":["Eosinophilia: parasites, allergy (< 1,000) vs clonal (> 1,000); HES > 1,500.","Eosinophilia (persistent &gt; 400/mm³): reactive (usually &lt; 1,000: parasites , allergy such as asthma, eczema, drug reactions, inflammatory bowel disease, connective tissue disease) or clonal (usually &gt; 1,000: myeloproliferative neoplasms, chronic myeloid leukaemia); hypereosinophilic syndrome (&gt; 1,500 persistently) can damage the heart and lungs.","Role: defence against parasites , allergy, chronic inflammation."],"dp":[]},"hemato1-wbc-1:e9":{"s":2,"u":["Basophils: histamine granules; normal < 200/mm³ in this lecture.","Basophils : normal 0-200/mm³; 10-15 µm, lobulated nucleus hidden by large dark granules containing histamine , serotonin and peroxidase; a few hours in blood then tissues; basophilia &gt; 200/mm³ (e.g. myeloproliferative disorders)."],"dp":[]}},"meta":{"1cyvoi3":{"a":"recall","vg":"hemato1-wbc-1:e2/recall/1"},"5vgyog":{"a":"recall","vg":"hemato1-wbc-1:e1/recall/1"},"mvczku":{"a":"recall","vg":"hemato1-wbc-1:e0/recall/1"},"136reft":{"a":"recall","vg":"hemato1-wbc-1:e2/recall/2"},"14g5iym":{"a":"recall","vg":"hemato1-wbc-1:e2/recall/3"},"r1zy1o":{"a":"recall","vg":"hemato1-wbc-1:e4/recall/1"},"1kwolbh":{"a":"recall","vg":"hemato1-wbc-1:e4/recall/2"},"b82khx":{"a":"relationship","vg":"hemato1-wbc-1:e3/relationship/1"},"ch55vw":{"a":"recall","vg":"hemato1-wbc-1:e5/recall/1"},"15khw61":{"a":"recall","vg":"hemato1-wbc-1:e6/recall/1"},"b7uff3":{"a":"recall","vg":"hemato1-wbc-1:e7/recall/1"},"116rdtj":{"a":"relationship","vg":"hemato1-wbc-1:e8/relationship/1"},"ykiku2":{"a":"recall","vg":"hemato1-wbc-1:e8/recall/1"},"vcrwjx":{"a":"recall","vg":"hemato1-wbc-1:e9/recall/1"}},"explRev":"bb5619bb5568"};
